/* Layout Wrapper */
.calculator-layout-wrapper {
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: flex-start;
  gap: 24px;
  width: 100%;
  max-width: 800px;
  padding: 16px;
  box-sizing: border-box;
}

/* Control Header Bar */
.control-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  background-color: var(--bg-screen);
  border-radius: 12px;
  padding: 8px 12px;
  border: 1px solid #333;
  width: 100%;
  box-sizing: border-box;
}

.btn-control-toggle {
  background: transparent;
  border: 1px solid #444;
  color: #ccc;
  border-radius: 6px;
  padding: 4px 10px;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
}

.btn-control-toggle:hover {
  background-color: #333;
  color: #fff;
  border-color: #666;
}

.btn-control-toggle.active {
  background-color: var(--btn-eval);
  color: #fff;
  border-color: var(--btn-eval);
}

.memory-badge {
  background-color: var(--btn-op);
  color: white;
