  background-color: #5c1d1d;
  color: #ff9e9e;
  border: 1px solid #7c2d2d;
  border-radius: 8px;
  padding: 10px 0;
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: bold;
  transition: all 0.15s ease;
}

.btn-clear-history:hover {
  background-color: #7c2d2d;
  color: #ffffff;
}

